<header class="page-header"><div><p class="eyebrow">Daily work</p><h1>Next actions</h1><p>Work overdue actions first, then today, then upcoming.</p></div></header><?php foreach(['overdue'=>'Overdue','today'=>'Today','upcoming'=>'Upcoming'] as $key=>$heading):?><section><h2><?= $escape($heading) ?></h2><?php if($queues[$key]===[]):?><p>Nothing <?= strtolower($heading) ?>.</p><?php else:?><ol class="timeline"><?php foreach($queues[$key] as $item):?><li><strong><?= $escape($item['company_name']?:$item['contact_name']) ?></strong> — <?= $escape($item['action']) ?> <time><?= $escape($item['due_at']) ?></time><form class="inline-form" method="post" action="<?= $escape($completeUrl((int)$item['id'])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($item['version']) ?>"><button>Complete</button></form><form class="inline-form" method="post" action="<?= $escape($rescheduleUrl((int)$item['id'])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($item['version']) ?>"><input type="hidden" name="prospect_version" value="<?= $escape($item['prospect_version']) ?>"><label>New action<input name="action" value="<?= $escape($item['action']) ?>" required></label><label>New due time<input type="datetime-local" name="due_at" required></label><button>Reschedule</button></form><form class="inline-form" method="post" action="<?= $escape($cancelUrl((int)$item['id'])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($item['version']) ?>"><input type="hidden" name="reason" value="Cancelled from daily work"><button>Cancel</button></form></li><?php endforeach;?></ol><?php endif;?></section><?php endforeach;?>
